contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount, address target, bytes calldata data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        uint beforeBal = address(c).balance;

        bool commandReverted;
        c.Command{value: amount}(target, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            commandReverted = true;
        } else {
            commandReverted = false;
        }

        assert(commandReverted || address(c).balance >= beforeBal || address(target).balance >= amount);
    }
}

